package cn.sixnine.filmlog;

import android.app.*;
import android.os.Bundle;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import java.util.*;
import java.util.function.Consumer;

/** One reusable camera draft: model -> confirmation -> optional logo choice. */
final class CameraEditor {
    private final Activity activity;
    private final CatalogStore catalog;
    private final Bundle draft;
    private final Consumer<String> saved;
    private final Runnable cancelled;
    private Dialog dialog;
    private LinearLayout root,body,footer,logoHero;
    private TextView error;
    private boolean closing;

    static Dialog show(Activity activity,LogStore logs,Bundle state,CatalogStore.Entry old,Consumer<String> saved,Runnable cancelled){CameraEditor editor=new CameraEditor(activity,logs,state,old,saved,cancelled);editor.open();return editor.dialog;}
    private CameraEditor(Activity a,LogStore logs,Bundle state,CatalogStore.Entry old,Consumer<String> save,Runnable cancel){activity=a;catalog=new CatalogStore(logs);draft=state;saved=save;cancelled=cancel;
        if(!draft.containsKey("screen")){draft.putString("screen",old==null?"models":"confirm");draft.putString("id",old==null?"":old.id);draft.putString("model",old==null?"":old.cameraModel.isEmpty()?old.name:old.cameraModel);draft.putString("nickname",old==null||old.cameraModel.isEmpty()||old.name.equals(old.cameraModel)?"":old.name);draft.putString("format",old==null?"35 mm":old.format);draft.putString("notes",old==null?"":old.notes);draft.putString("condition",old==null?"":old.condition);draft.putString("logo",old==null?"":old.cameraLogo);draft.putBoolean("favorite",old!=null&&old.favorite);draft.putBoolean("showBrand",old!=null&&old.cameraShowBrand);}
    }
    private String get(String key){return draft.getString(key,"");}
    private int dp(int value){return Math.round(value*activity.getResources().getDisplayMetrics().density);}
    private int color(int id){return activity.getColor(id);}
    private LinearLayout column(){LinearLayout l=new LinearLayout(activity);l.setOrientation(1);return l;}
    private GradientDrawable surface(boolean selected){GradientDrawable d=new GradientDrawable();d.setColor(color(R.color.ui_card));d.setCornerRadius(dp(8));d.setStroke(dp(1),color(selected?R.color.ui_accent:R.color.ui_outline));return d;}
    private TextView text(String s,int size,int id){TextView t=new TextView(activity);t.setText(s);t.setTextSize(size);t.setTextColor(color(id));t.setIncludeFontPadding(false);return t;}
    private Button button(String label,boolean primary,Runnable run){Button b=UiSpacing.button(activity);b.setText(label);b.setAllCaps(false);b.setTextSize(14);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(dp(48));b.setPadding(dp(12),dp(8),dp(12),dp(8));b.setStateListAnimator(null);b.setElevation(0);b.setBackgroundTintList(null);GradientDrawable bg=surface(false);if(primary){bg.setColor(color(R.color.ui_accent));bg.setStroke(0,0);}b.setBackground(bg);b.setTextColor(color(primary?R.color.ui_on_accent:R.color.ui_accent));b.setOnClickListener(v->run.run());return b;}
    private TextWatcher watch(Consumer<String> changed){return new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int b,int c){}public void onTextChanged(CharSequence s,int a,int b,int c){changed.accept(s.toString());}public void afterTextChanged(Editable e){}};}
    private EditText edit(String key,String hint){EditText e=new EditText(activity);e.setSingleLine();e.setTextSize(15);e.setTextColor(color(R.color.ui_ink));e.setHintTextColor(color(R.color.ui_muted));e.setHint(hint);e.setContentDescription(hint);e.setBackgroundTintList(null);e.setBackground(surface(false));e.setPadding(dp(12),dp(10),dp(12),dp(10));e.setText(get(key));e.setMinHeight(dp(46));e.addTextChangedListener(watch(s->{draft.putString(key,s);if(key.equals("model")&&!draft.getBoolean("logoExplicit")){draft.putString("logo",CameraLogos.suggest(activity,s));refreshHero();}}));return e;}
    private void gap(LinearLayout p,int n){p.addView(new View(activity),new LinearLayout.LayoutParams(1,dp(n)));}
    private void open(){dialog=new Dialog(activity,R.style.FilmDialog);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);dialog.setOnCancelListener(d->cancel());dialog.setOnKeyListener((d,key,event)->{if(key!=KeyEvent.KEYCODE_BACK)return false;if(event.getAction()==KeyEvent.ACTION_UP)back();return true;});render();dialog.show();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setGravity(Gravity.BOTTOM);w.setLayout(-1,Math.round(activity.getResources().getDisplayMetrics().heightPixels*.9f));w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}}
    private void hideKeyboard(){if(dialog.getWindow()!=null)((InputMethodManager)activity.getSystemService(Activity.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(dialog.getWindow().getDecorView().getWindowToken(),0);}
    private void cancel(){if(closing)return;closing=true;hideKeyboard();dialog.dismiss();cancelled.run();}
    private void back(){if(get("screen").equals("logos")){draft.putString("screen","confirm");render();}else if(get("screen").equals("models")&&!get("model").isEmpty()){draft.putString("screen","confirm");render();}else cancel();}
    private void render(){hideKeyboard();root=column();root.setClipToPadding(false);root.setPadding(dp(20),dp(8),dp(20),dp(16));GradientDrawable background=new GradientDrawable();background.setColor(color(R.color.ui_background));background.setCornerRadius(dp(18));root.setBackground(background);
        String screen=get("screen");root.addView(LibraryUi.header(activity,screen.equals("models")?"选择相机型号":screen.equals("logos")?"选择 Logo":get("id").isEmpty()?"添加相机":"编辑相机",this::back,null,20));
        body=column();root.addView(body,new LinearLayout.LayoutParams(-1,0,1));footer=column();gap(footer,12);root.addView(footer);dialog.setContentView(root);
        if(screen.equals("models"))models();else if(screen.equals("logos"))logos();else confirm();
    }
    private Spinner brandFilter(Collection<String> brands,String key,String label,Runnable updated){ArrayList<String> values=new ArrayList<>();values.add("全部品牌");TreeSet<String> sorted=new TreeSet<>(brands);sorted.remove("");values.addAll(sorted);Spinner spinner=new Spinner(activity);spinner.setContentDescription(label);spinner.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,values));spinner.setSelection(Math.max(0,values.indexOf(get(key))));spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int index,long id){draft.putString(key,index==0?"":values.get(index));updated.run();}public void onNothingSelected(AdapterView<?> p){}});return spinner;}
    private void models(){gap(body,16);body.addView(text("找到你的相机",27,R.color.ui_ink));gap(body,6);body.addView(text("选择型号后，为它选一枚合适的 Logo。",12,R.color.ui_muted));gap(body,16);EditText search=edit("modelQuery","搜索品牌或型号");body.addView(search);gap(body,8);
        ArrayList<OriginalCatalog.Camera> all=OriginalCatalog.cameras(activity),shown=new ArrayList<>();ListView list=new ListView(activity);list.setDividerHeight(dp(1));body.addView(list,new LinearLayout.LayoutParams(-1,0,1));ArrayAdapter<String> adapter=new ArrayAdapter<String>(activity,android.R.layout.simple_list_item_1,new ArrayList<String>()){@Override public View getView(int p,View recycled,ViewGroup parent){TextView t=(TextView)super.getView(p,recycled,parent);t.setTextColor(color(R.color.ui_ink));t.setTextSize(15);t.setMinHeight(dp(68));return t;}};list.setAdapter(adapter);
        Runnable update=()->{adapter.clear();shown.clear();String q=get("modelQuery").trim().toLowerCase(Locale.ROOT);for(OriginalCatalog.Camera c:all){String brand=CameraLogos.brand(activity,c.name);String aliases=CameraLogos.aliases(brand);if(!get("modelBrand").isEmpty()&&!get("modelBrand").equals(brand))continue;if(!(c.name+" "+aliases).toLowerCase(Locale.ROOT).contains(q))continue;shown.add(c);adapter.add(c.name+"\n"+(c.filmFormat().isEmpty()?"规格待确认":c.filmFormat()));}adapter.notifyDataSetChanged();};TreeSet<String> brands=new TreeSet<>();for(OriginalCatalog.Camera c:all)brands.add(CameraLogos.brand(activity,c.name));body.addView(brandFilter(brands,"modelBrand","筛选相机品牌",update),body.indexOfChild(list),new LinearLayout.LayoutParams(-1,dp(44)));search.addTextChangedListener(watch(s->update.run()));list.setOnItemClickListener((p,v,index,id)->{OriginalCatalog.Camera c=shown.get(index);draft.putString("model",c.name);draft.putString("format",c.filmFormat());draft.putString("logo",CameraLogos.suggest(activity,c.name));draft.putBoolean("logoExplicit",false);draft.putBoolean("manual",false);draft.putString("screen","confirm");render();});update.run();
        footer.addView(button("没有找到？手动添加",false,()->{draft.putString("model","");draft.putString("logo","");draft.putBoolean("manual",true);draft.putBoolean("logoExplicit",false);draft.putString("screen","confirm");render();}));
    }
    private void refreshHero(){if(logoHero==null)return;logoHero.removeAllViews();CameraLogos.Logo l=CameraLogos.find(activity,get("logo"));if(l!=null)logoHero.addView(CameraLogos.view(activity,l.id),new LinearLayout.LayoutParams(dp(190),dp(40)));else{TextView generic=text(String.valueOf((char)0xe10e),30,R.color.ui_muted);generic.setTypeface(Typeface.createFromAsset(activity.getAssets(),"fonts/Phosphor.ttf"));generic.setGravity(Gravity.CENTER);logoHero.addView(generic,new LinearLayout.LayoutParams(dp(190),dp(40)));}
        logoHero.addView(button("更换 Logo  ›",false,()->{draft.putString("pendingLogo",get("logo"));draft.putString("logoQuery","");draft.putString("logoMode","recommended");draft.putString("logoBrand","");draft.putString("screen","logos");render();}));TextView caption=text(l==null?"通用相机图标":(CameraLogos.exact(l,get("model"))?"型号字标":"品牌标志")+" · "+l.brand,11,R.color.ui_muted);caption.setGravity(Gravity.CENTER);logoHero.addView(caption);
    }
    private void field(LinearLayout parent,String key,String label){parent.addView(text(label,12,R.color.ui_muted));gap(parent,6);parent.addView(edit(key,label),new LinearLayout.LayoutParams(-1,-2));gap(parent,16);}
    private void confirm(){ScrollView scroll=new ScrollView(activity);LinearLayout form=column();scroll.addView(form);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));gap(form,12);logoHero=column();logoHero.setGravity(Gravity.CENTER);logoHero.setPadding(dp(16),dp(16),dp(16),dp(12));logoHero.setBackground(surface(false));form.addView(logoHero);refreshHero();gap(form,20);
        if(draft.getBoolean("manual"))field(form,"model","相机型号");else{form.addView(text("相机型号",12,R.color.ui_muted));gap(form,10);TextView model=text(get("model"),19,R.color.ui_ink);model.setContentDescription("相机型号："+get("model"));form.addView(model);gap(form,8);}
        CheckBox brandName=new CheckBox(activity);brandName.setText("首页显示品牌名称");brandName.setTextColor(color(R.color.ui_ink));brandName.setChecked(draft.getBoolean("showBrand"));brandName.setOnCheckedChangeListener((button,checked)->draft.putBoolean("showBrand",checked));form.addView(brandName);gap(form,8);
        form.addView(button("重新选择型号  ›",false,()->{draft.putString("screen","models");render();}));gap(form,12);form.addView(text("胶片规格",12,R.color.ui_muted));Spinner formats=new Spinner(activity);ArrayList<String> values=new ArrayList<>(Arrays.asList("35 mm","120","110","4x5","5x7","8x10","其他",""));if(!values.contains(get("format")))values.add(get("format"));ArrayList<String> labels=new ArrayList<>();for(String value:values)labels.add(value.isEmpty()?"暂不限定":value);ArrayAdapter<String> a=new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,labels);formats.setAdapter(a);formats.setSelection(Math.max(0,values.indexOf(get("format"))));formats.setContentDescription("胶片规格");formats.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){draft.putString("format",values.get(pos));}public void onNothingSelected(AdapterView<?> p){}});form.addView(formats,new LinearLayout.LayoutParams(-1,dp(48)));gap(form,12);
        LinearLayout more=column();more.setVisibility(draft.getBoolean("more")?View.VISIBLE:View.GONE);form.addView(button("更多信息  ＋",false,()->{boolean open=more.getVisibility()!=View.VISIBLE;more.setVisibility(open?View.VISIBLE:View.GONE);draft.putBoolean("more",open);}));form.addView(more);gap(more,12);field(more,"nickname","昵称（可选）");field(more,"notes","备注（可选）");field(more,"condition","成色（可选）");CheckBox favorite=new CheckBox(activity);favorite.setText("收藏这台相机");favorite.setTextColor(color(R.color.ui_ink));favorite.setChecked(draft.getBoolean("favorite"));favorite.setOnCheckedChangeListener((b,checked)->draft.putBoolean("favorite",checked));more.addView(favorite);error=text("",12,R.color.ui_error);form.addView(error);
        footer.addView(button("保存相机",true,()->{try{String id=catalog.saveCamera(get("id"),get("model"),get("nickname"),get("format"),get("notes"),get("condition"),draft.getBoolean("favorite"),get("logo"),draft.getBoolean("showBrand"));closing=true;hideKeyboard();dialog.dismiss();saved.accept(id);}catch(Exception invalid){error.setText(invalid.getMessage()==null?"保存未完成，请核对输入":invalid.getMessage());}}));
    }
    private void logos(){EditText search=edit("logoQuery","搜索品牌或字标");gap(body,12);body.addView(search);gap(body,8);LinearLayout tabs=new LinearLayout(activity);Button recommended=button("推荐",!get("logoMode").equals("all"),()->{draft.putString("logoMode","recommended");render();}),all=button("全部素材",get("logoMode").equals("all"),()->{draft.putString("logoMode","all");render();});tabs.addView(recommended,new LinearLayout.LayoutParams(0,dp(48),1));tabs.addView(all,new LinearLayout.LayoutParams(0,dp(48),1));body.addView(tabs);GridView grid=new GridView(activity);grid.setNumColumns(2);grid.setHorizontalSpacing(dp(8));grid.setVerticalSpacing(dp(8));body.addView(grid,new LinearLayout.LayoutParams(-1,0,1));ArrayList<CameraLogos.Logo> shown=new ArrayList<>();BaseAdapter adapter=new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int i){return shown.get(i);}public long getItemId(int i){return i;}public View getView(int i,View recycled,ViewGroup p){CameraLogos.Logo l=shown.get(i);LinearLayout tile=column();tile.setPadding(dp(10),dp(12),dp(10),dp(12));tile.setBackground(surface(l.id.equals(get("pendingLogo"))));tile.addView(CameraLogos.view(activity,l.id),new LinearLayout.LayoutParams(-1,dp(44)));gap(tile,10);TextView label=text(l.label,11,R.color.ui_muted);label.setMaxLines(2);tile.addView(label);tile.setMinimumHeight(dp(112));tile.setContentDescription(l.label+(l.id.equals(get("pendingLogo"))?"，已选择":""));return tile;}};grid.setAdapter(adapter);Runnable update=()->{shown.clear();Collection<CameraLogos.Logo> choices=get("logoMode").equals("all")?CameraLogos.all(activity):CameraLogos.recommended(activity,get("model"));String q=get("logoQuery").trim().toLowerCase(Locale.ROOT);for(CameraLogos.Logo l:choices)if((get("logoBrand").isEmpty()||l.brand.equals(get("logoBrand")))&&(l.label+" "+l.brand+" "+l.model+" "+CameraLogos.aliases(l.brand)).toLowerCase(Locale.ROOT).contains(q))shown.add(l);adapter.notifyDataSetChanged();};TreeSet<String> brands=new TreeSet<>();for(CameraLogos.Logo l:CameraLogos.all(activity))brands.add(l.brand);body.addView(brandFilter(brands,"logoBrand","筛选Logo品牌",update),body.indexOfChild(grid),new LinearLayout.LayoutParams(-1,dp(44)));search.addTextChangedListener(watch(s->update.run()));grid.setOnItemClickListener((p,v,i,id)->{draft.putString("pendingLogo",shown.get(i).id);adapter.notifyDataSetChanged();});update.run();footer.addView(button("使用通用相机图标",false,()->{draft.putString("pendingLogo","");adapter.notifyDataSetChanged();}));footer.addView(button("使用这个 Logo",true,()->{draft.putString("logo",get("pendingLogo"));draft.putBoolean("logoExplicit",true);draft.putString("screen","confirm");render();}));
    }
}
